'use strict';

/**
 * Run-length encoding with digit escaping.
 *
 * - Runs of length >= 2 become "<count><char>" (e.g. "aaab" -> "3ab").
 * - Single characters pass through unchanged.
 * - Literal digits and backslashes in the input are prefixed with '\'
 *   so decode is unambiguous.
 */

function encode(s) {
  let out = '';
  let i = 0;
  while (i < s.length) {
    const ch = s[i];
    // Digits and backslashes must be escaped; no run-length form for them,
    // so every occurrence gets its own backslash prefix.
    if (ch === '\\' || (ch >= '0' && ch <= '9')) {
      out += '\\' + ch;
      i++;
      continue;
    }
    let j = i;
    while (j < s.length && s[j] === ch) j++;
    const count = j - i;
    out += count >= 2 ? String(count) + ch : ch;
    i = j;
  }
  return out;
}

function decode(s) {
  let out = '';
  let i = 0;
  while (i < s.length) {
    const ch = s[i];
    if (ch === '\\') {
      // Escaped literal character (digit or backslash).
      if (i + 1 >= s.length) throw new Error('trailing escape at end of input');
      out += s[i + 1];
      i += 2;
      continue;
    }
    if (ch >= '0' && ch <= '9') {
      // Run length: consume all consecutive digits.
      let j = i;
      while (j < s.length && s[j] >= '0' && s[j] <= '9') j++;
      const count = parseInt(s.slice(i, j), 10);
      if (j >= s.length) throw new Error('run length without character');
      out += s[j].repeat(count);
      i = j + 1;
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

module.exports = { encode, decode };

