'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { encode, decode } = require('./rle.js');

// Seeded xorshift32 PRNG, written inline per spec.
function makeRng(seed) {
  let state = seed >>> 0;
  return function rng() {
    state ^= state << 13; state >>>= 0;
    state ^= state >> 17;
    state ^= state << 5; state >>>= 0;
    return state / 0x100000000;
  };
}

test('"aaab" encodes to "3ab"', () => {
  assert.equal(encode('aaab'), '3ab');
});

test('empty string', () => {
  assert.equal(encode(''), '');
  assert.equal(decode(''), '');
});

test('1000 identical chars', () => {
  const s = 'x'.repeat(1000);
  assert.equal(encode(s), '1000x');
  assert.equal(decode('1000x'), s);
});

test('all-digit strings are escaped and round-trip', () => {
  for (const s of ['1234567890', '7777777', '9', '00']) {
    const e = encode(s);
    // No raw digit may appear unescaped in the encoding.
    for (let i = 0; i < e.length; i++) {
      if (e[i] >= '0' && e[i] <= '9') {
        assert.equal(e[i - 1], '\\', `unescaped digit at ${i} in ${JSON.stringify(e)}`);
      }
    }
    assert.equal(decode(e), s);
  }
});

test('round-trip on 500 random strings from "aab3\\\\x"', () => {
  const rng = makeRng(0xc0ffee);
  const alphabet = ['a', 'a', 'b', '3', '\\', 'x']; // biased toward 'a'
  for (let t = 0; t < 500; t++) {
    const len = Math.floor(rng() * 60);
    let s = '';
    for (let i = 0; i < len; i++) {
      s += alphabet[Math.floor(rng() * alphabet.length)];
    }
    const decoded = decode(encode(s));
    assert.equal(decoded, s, `round-trip failed for ${JSON.stringify(s)}`);
  }
});

